python3 - <<'PY'
from pathlib import Path
p = Path('/etc/nginx/nginx.conf')
s = p.read_text()
block = '''
\t# Benchmark custom log format
\tlog_format benchmark '$remote_addr - $remote_user [$time_local] "$request" '
\t                     '$request_method $status "$http_user_agent"';

\t# Rate limiting zone: 10 requests/second per IP, 10MB memory zone
\tlimit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;
'''
if 'log_format benchmark' not in s:
    s = s.replace('http {\n', 'http {\n' + block, 1)
if 'limit_req_zone $binary_remote_addr zone=benchmark_limit' not in s:
    s = s.replace('http {\n', 'http {\n\n\tlimit_req_zone $binary_remote_addr zone=benchmark_limit:10m rate=10r/s;\n', 1)
p.write_text(s)
PY
mkdir -p /var/www/html
rm -f /etc/nginx/sites-enabled/default
printf '%s\n' 'Welcome to the benchmark webserver' > /var/www/html/index.html
printf '%s\n' 'Page not found - Please check your URL' > /var/www/html/404.html
cat > /etc/nginx/conf.d/benchmark-site.conf <<'EOF'
server {
    listen 8080;
    server_name localhost;

    root /var/www/html;
    index index.html;

    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    limit_req zone=benchmark_limit burst=10 nodelay;

    location / {
        try_files $uri $uri/ =404;
    }

    error_page 404 /404.html;
    location = /404.html {
        internal;
    }
}
EOF
nginx -t
